BOOL Release() {
    if (!g_bD3DCoreInitialized) {
      return 1;
    }

    RENDERER_D3D_ReleaseSmackerBuffer();
    RENDERER_D3D_ReleaseDevice();
    gnGlideWindowHandle = 0;
    if (g_pDirect3D7) {
      g_pDirect3D7->lpVtbl->Release(g_pDirect3D7);
      g_pDirect3D7 = 0;
    }
    if (g_pDirectDraw7) {
      g_pDirectDraw7->lpVtbl->Release(g_pDirectDraw7);
      g_pDirectDraw7 = 0;
    }
    if (RENDERER_SelectedRendererCore) {
      /* LPCRITICAL_SECTION lpCriticalSection for DeleteCriticalSection */ DeleteCriticalSection(&RENDERER_SelectedRendererCore->sLock);
      D2_FREE_AT(RENDERER_SelectedRendererCore, ".\\Src\\d3dCore.cpp", 0x71d);
      RENDERER_SelectedRendererCore = 0;
    }

    g_bD3DCoreInitialized = 0;
    return 1;
}

BOOL __fastcall CreateWindow(HWND hWnd, int nResolutionMode) {
    if (g_bDeviceInitialized) {
      return 1;
    }

    BOOL BVar2 = RENDERER_D3D_InitializeDevice(nResolutionMode, (int)hWnd);
    if (!BVar2) {
      return 0;
    }

    RENDERER_D3D_ClearBackbuffer();
    DDS_Flip pDVar1 = g_pD3DSurfaceBackbuffer->lpVtbl->Flip;
    if (pD2GFXRenderedDataStrc->bVSync) {
      (*pDVar1)(g_pD3DSurfaceBackbuffer, nullptr, 1);
      return 1;
    }

    (*pDVar1)(g_pD3DSurfaceBackbuffer, nullptr, 9);
    return 1;
}

void __fastcall EndCutScene(HWND hWnd, int nResolutionMode, int nWindowState) {
    if (!RENDERER_SelectedRendererCore) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x7b0);
      exit(-1);
    }

    /* LPCRITICAL_SECTION lpCriticalSection for EnterCriticalSection */ EnterCriticalSection(&RENDERER_SelectedRendererCore->sLock);
    if (nWindowState) {
      gnRenderState = 1;
      RENDERER_D3D_ReleaseDevice();
      /* LPCRITICAL_SECTION lpCriticalSection for LeaveCriticalSection */ gnGlideWindowHandle = 0;
      LeaveCriticalSection(&RENDERER_SelectedRendererCore->sLock);
      return;
    }

    gnRenderState = 0;
    Renderer::CreateWindow(hWnd, nResolutionMode);
    /* LPCRITICAL_SECTION lpCriticalSection for LeaveCriticalSection */ LeaveCriticalSection(&RENDERER_SelectedRendererCore->sLock);
}

void __fastcall PlayCutScene(char * szFile, int nResolutionMode, void * fpFrame) {
    DWORD dwFlags;
    if (gnRenderState) {
      return;
    }

    g_bCutscenePlaying = 1;
    RENDERER_D3D_ClearBackbuffer();
    if (pD2GFXRenderedDataStrc->bVSync) {
      dwFlags = 1;
    } else {
      dwFlags = 9;
    }

    g_pD3DSurfaceBackbuffer->lpVtbl->Flip(g_pD3DSurfaceBackbuffer, nullptr, dwFlags);
    Fog::d3dFloorCache::D3D_PlayBinkVideo(szFile, nResolutionMode, (fnBinkFrameCallback)fpFrame);
    g_bCutscenePlaying = 0;
}

BOOL __fastcall BeginScene(BOOL bClear, BYTE nRed, BYTE nGreen, BYTE nBlue) {
    if (gnRenderState) {
      return 0;
    }
    if (!RENDERER_SelectedRendererCore) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x842);
      exit(-1);
    }

    /* LPCRITICAL_SECTION lpCriticalSection for EnterCriticalSection */ EnterCriticalSection(&RENDERER_SelectedRendererCore->sLock);
    if (bClear) {
      Renderer::ClearScreen(0);
    }

    g_nCurrentTextureOpMode = 0;
    g_nCurrentAlphaBlendMode = 0;
    g_nCurrentFilterMode = 0;
    Renderer::SetGlobalLight(0xff, 0xff, 0xff);
    DWORD dwParam = g_pD3DDevice->lpVtbl->BeginScene(g_pD3DDevice);
    if (!dwParam) {
      return 1;
    }

    RENDERER_DIRECT3D_ErrorLog("BeginScene failed!", dwParam);
    return 1;
}

BOOL EndScene1() {
    DWORD dwParam = g_pD3DDevice->lpVtbl->EndScene(g_pD3DDevice);
    if (dwParam) {
      RENDERER_DIRECT3D_ErrorLog("EndScene failed!", dwParam);
    }
    if (!RENDERER_SelectedRendererCore) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x8b3);
      exit(-1);
    }

    /* LPCRITICAL_SECTION lpCriticalSection for LeaveCriticalSection */ LeaveCriticalSection(&RENDERER_SelectedRendererCore->sLock);
    return 1;
}

BOOL __fastcall ResizeWindow(HWND hWnd, BOOL bForceResize) {
    if (gnRenderState) {
      return 1;
    }

    RENDERER_D3D_ReleaseDevice();
    gnGlideWindowHandle = 0;
    BOOL BVar2 = RENDERER_D3D_InitializeDevice(bForceResize, (int)hWnd);
    if (!BVar2) {
      return 0;
    }

    RENDERER_D3D_ClearBackbuffer();
    DDS_Flip pDVar1 = g_pD3DSurfaceBackbuffer->lpVtbl->Flip;
    if (pD2GFXRenderedDataStrc->bVSync) {
      (*pDVar1)(g_pD3DSurfaceBackbuffer, nullptr, 1);
      return 1;
    }

    (*pDVar1)(g_pD3DSurfaceBackbuffer, nullptr, 9);
    return 1;
}

